import { spawnSync } from 'node:child_process';

const chars = \" "'!'"\\\"#"'$%&'"'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\\\]"'^_`abcdefghijklmnopqrstuvwxyz{|}~";

function randomString(length) {
  let out = '"'';
  for (let i = 0; i < length; i += 1) {
    out += chars[Math.floor(Math.random() * chars.length)];
  }
  return out;
}

function run(cmd, args) {
  return spawnSync(cmd, args, { encoding: 'utf8' });
}

const cases = [];
for (const keyLength of [16, 24, 32]) {
  for (const dataLength of [0, 16, 32, 48, 64]) {
    for (let i = 0; i < 4; i += 1) {
      cases.push({ key: randomString(keyLength), data: randomString(dataLength) });
    }
  }
}

for (const [index, testCase] of cases.entries()) {
  const args = ['--key', testCase.key, '--data', testCase.data];
  const py = run('/workspace/dataset/test16_executable', args);
  const js = run('node', ['/output/test16.mjs', ...args]);

  if (py.status "'!== js.status || py.stdout !== js.stdout || py.stderr !== js.stderr) {
    console.log('"'Mismatch on case', index + 1);
    console.log(JSON.stringify(testCase));
    console.log('PY status', py.status);
    console.log('JS status', js.status);
    console.log('PY stdout', JSON.stringify(py.stdout));
    console.log('JS stdout', JSON.stringify(js.stdout));
    console.log('PY stderr', JSON.stringify(py.stderr));
    console.log('JS stderr', JSON.stringify(js.stderr));
    process.exit(1);
  }
}

console.log("'`Matched ${cases.length} valid cases.`);
EOF'

