/bin/bash -lc "node --input-type=module - <<'EOF'
import { spawnSync } from 'node:child_process';

function run(cmd, args) {
  return spawnSync(cmd, args, { encoding: 'utf8' });
}

function normalize(text) {
  return text
    .replaceAll('test16_executable', 'PROGRAM')
    .replaceAll('test16.mjs', 'PROGRAM')
    .replace(/\\[PYI-\\d+:ERROR\\]/g, '[PYI-PID:ERROR]');
}

const cases = [
  [],
  ['--help'],
  ['--foo', 'bar'],
  ['--key'],
  ['--key', '1234567890123456', '--foo', 'bar'],
  ['--key', '-x', '--data', 'abcdefghijklmnop'],
  ['--key', 'abc', '--data', 'abcdefghijklmnop'],
  ['--key', 'AAAAAAAAAAAAAAAA', '--data', 'abcdefghijklmnopabc'],
  ['--foo', '-h'],
  ['--', '--help'],
];

for (const args of cases) {
  const py = run('/workspace/dataset/test16_executable', args);
  const js = run('node', ['/output/test16.mjs', ...args]);
  const same = py.status === js.status && normalize(py.stdout) === normalize(js.stdout) && normalize(py.stderr) === normalize(js.stderr);
  if ("'!same) {
    console.log('"'Mismatch', JSON.stringify(args));
    console.log('PY status', py.status, 'JS status', js.status);
    console.log('PY stdout', JSON.stringify(py.stdout));
    console.log('JS stdout', JSON.stringify(js.stdout));
    console.log('PY stderr', JSON.stringify(normalize(py.stderr)));
    console.log('JS stderr', JSON.stringify(normalize(js.stderr)));
    process.exit(1);
  }
}

console.log("'`Matched ${cases.length} normalized edge cases.`);
EOF'

